{"explanation":"Each ball hits 8 rows of pegs and bounces left or right with probability 1/2 at each one. Its final bin is the number of right bounces, which follows Binomial(8, 1/2). As balls pile up, the bars take the bell shape and approach the yellow theoretical dots. Use the button to drop more balls.","manimCode":"const n = 8, dx = 0.6, dy = 0.38, top = 3.1, base = -2.6;
const rowY = r => top - r * dy;

// pegs
for (let r = 0; r < n; r++) {
  for (let j = 0; j <= r; j++) {
    scene.add(new Dot({ point: [(j - r / 2) * dx, rowY(r), 0], color: GRAY, radius: 0.05 }));
  }
}
// bin dividers + baseline
const floor = new Line({ start: [-2.9, base, 0], end: [2.9, base, 0], color: WHITE });
scene.add(floor);
for (let k = 0; k <= n + 1; k++) {
  const x = (k - 4.5) * dx;
  scene.add(new Line({ start: [x, base, 0], end: [x, base + 2.3, 0], color: GRAY_D || GRAY, strokeWidth: 1 }));
}

// theoretical binomial
function choose(a, b) { let r = 1; for (let i = 1; i <= b; i++) r = r * (a - b + i) / i; return r; }
const pmf = k => choose(n, k) / Math.pow(2, n);
const S = 6; // height scale
for (let k = 0; k <= n; k++) {
  scene.add(new Dot({ point: [(k - 4) * dx, base + pmf(k) * S, 0], color: YELLOW, radius: 0.07 }));
}
const legend = new Text({ text: 'yellow dots: Binomial(8, 1/2)', color: YELLOW, fontSize: 22 });
legend.moveTo([4.6, 2.4, 0]);
scene.add(legend);
const title = new Text({ text: 'Galton Board', color: WHITE, fontSize: 36 });
title.moveTo([-4.5, 3.2, 0]);
scene.add(title);

const counts = new Array(n + 1).fill(0);
let total = 0;
let bars = [];
let info = null;
function redraw() {
  bars.forEach(b => scene.remove(b));
  bars = [];
  for (let k = 0; k <= n; k++) {
    if (counts[k] === 0) continue;
    const h = Math.max(0.02, counts[k] / total * S);
    const b = new Rectangle({ width: dx * 0.85, height: h, color: BLUE });
    b.setFill(BLUE, 0.7);
    b.moveTo([(k - 4) * dx, base + h / 2, 0]);
    scene.add(b);
    bars.push(b);
  }
  if (info) scene.remove(info);
  info = new Text({ text: 'Balls: ' + total, color: WHITE, fontSize: 26 });
  info.moveTo([-4.5, 2.4, 0]);
  scene.add(info);
}
redraw();

async function dropBall() {
  const ball = new Dot({ point: [0, top + 0.6, 0], color: RED, radius: 0.1 });
  scene.add(ball);
  let x = 0, y = top + 0.6;
  let k = 0;
  for (let r = 0; r < n; r++) {
    const ty = rowY(r) + 0.15;
    await scene.play(new Shift(ball, { direction: [0, ty - y, 0], runTime: 0.06 }));
    y = ty;
    const right = Math.random() < 0.5;
    if (right) k++;
    const step = right ? dx / 2 : -dx / 2;
    const ny = (r < n - 1 ? rowY(r + 1) : rowY(n - 1) - dy) + 0.15;
    await scene.play(new Shift(ball, { direction: [step, ny - y, 0], runTime: 0.08 }));
    x += step; y = ny;
  }
  await scene.play(new Shift(ball, { direction: [0, base + 0.1 - y, 0], runTime: 0.1 }));
  scene.remove(ball);
  counts[k]++; total++;
  redraw();
}

let running = false;
async function dropMany(m) {
  if (running) return;
  running = true;
  for (let i = 0; i < m; i++) await dropBall();
  running = false;
}

const controls = new Controls(scene, { position: 'top-right' });
controls.addButton({ label: 'Drop 20 balls', onClick: () => { dropMany(20); } });
controls.addButton({ label: 'Reset', onClick: () => {
  if (running) return;
  counts.fill(0); total = 0; redraw();
} });

await dropMany(25);
await scene.wait(999999);"}

